pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(address owner, address spender, uint256 value) public {
        // Ensure caller (this contract) is authorized
        vm.assume(c.wards(address(this)) == 1);

        // Record wards before
        uint256 before = c.wards(address(this));

        // Call allowance (may revert, but state shouldn't change even on revert)
        (bool success,) = address(c).call(abi.encodeWithSignature("allowance(address,address)", owner, spender));

        // Assert wards unchanged
        assertTrue(c.wards(address(this)) == before);
    }
}

