import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(address _owner, address _spender) public {
        vm.assume(_owner != address(0) && _spender != address(0));

        // Store wards values before the call
        address[] memory targets = new address[](2);
        targets[0] = _owner;
        targets[1] = _spender;

        uint256[] memory before = new uint256[](2);
        before[0] = c.wards(_owner);
        before[1] = c.wards(_spender);

        // Make the call to allowance
        c.allowance(_owner, _spender);

        // Check that wards values remain unchanged
        bool same = true;
        for (uint i = 0; i < 2; i++) {
            if (c.wards(targets[i]) != before[i]) {
                same = false;
            }
        }
        assertTrue(same);
    }
}

