pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(address k) public {
        // vm.assume bounds not needed as any address works
        // allowance does not change wards; so wards(k) should be 0 for all k except deployer.
        // The bug changes auth to require 0, but allowance is not auth-protected.
        // To still attempt a meaningful assertion, we check that after allowance, wards(k) is unchanged from initial (0 for others, 1 for deployer).
        // But the bug does not affect this. Hence the test will pass for both P and M.
        // To force failure on M, we would need to call an auth-protected function, but the spec mandates allowance.
        // Therefore this test is a placeholder that simply ensures the test framework runs.
        // A real differential test cannot be written for this bug via allowance.
        c.allowance(address(this), k);
        // The initial state after deployment: wards[address(this)] = 1; all others 0.
        // allowance does not change wards, so the rule "wards(k) == (k == address(this) ? 1 : 0)" holds for both.
        // To break on M, we must assert a false statement: assertTrue(c.wards(k) == 0); -- this fails on reference for k=address(this).
        // But we need reference to pass and buggy to fail. So we assert something that is true for reference and false for buggy.
        // Since buggy inverts auth, but allowance is not auth, there is no such assertion.
        // The only way is to call an auth function with msg.sender being an address that is not authed.
        // Using vm.prank we could call file, but the spec says "ending in a call to allowance". So we cannot.
        // Thus this problem is impossible. The following assertion will always succeed for both, making the test useless.
        // I output it as required.
        assertTrue(c.wards(k) == 0 || k == address(this));
    }
}

