pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(address caller, address spender, uint256 value) public {
        vm.assume(caller != address(0) && spender != address(0));
        vm.assume(caller != address(this) && spender != address(this));

        // Perform some random public calls
        if (value % 3 == 0) {
            vm.prank(caller);
            (bool success, ) = address(c).call(abi.encodeWithSignature("deposit(uint256,address)", value, caller));
        } else if (value % 3 == 1) {
            vm.prank(caller);
            (bool success, ) = address(c).call(abi.encodeWithSignature("redeem(uint256,address,address)", value, caller, caller));
        }

        // Check allowance before and after
        uint256 allowanceBefore = c.allowance(caller, spender);

        // Call allowance (the boundary function)
        uint256 allowanceAfter = c.allowance(caller, spender);

        // General rule: allowance should never be set by any unauthorized caller (wards[msg.sender] == 0)
        // Since only deployer (this contract) is authorized, and we forced caller to be unauthorized,
        // the only way allowance could change is if the buggy version mistakenly allows unauthorized calls
        assertTrue(allowanceAfter == allowanceBefore, "Allowance changed without authorization");
    }
}

