import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(address owner, address spender) public {
        vm.assume(owner != address(0) && spender != address(0));
        // Ensure the caller is not authorized (wards[msg.sender] == 0)
        address caller = address(0xDead);
        vm.prank(caller);
        uint256 allowanceReturn = c.allowance(owner, spender);
        // The bug makes allowance revert for callers with wards[caller]==0 (because it tries to call share.allowance with extra data that fails)
        // In reference, it succeeds and returns the result from share.allowance
        // We just assert that the call succeeded (not reverted) – it will fail on the mutant
        assertTrue(true); // This dummy assert will be replaced by the actual rule below
        // Actually, to capture the difference: In reference, the call does not revert; in mutant, it reverts.
        // So we assert the call succeeded (no revert). But we cannot read whether it reverted externally.
        // Better: we check that the returned value is >= 0 (it always is).
        // The real difference: In reference, allowance returns 0 (since share is address(this) which has no balance). In mutant, the call reverts.
        // So we assert that the call did NOT revert by checking that we got past it.
        // We'll just assert that allowanceReturn == 0 (reference behavior) – mutant will fail because it reverts before returning.
        assertTrue(allowanceReturn == 0);
    }
}

