import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        // Record state before allowance call
        uint256 wardsBefore = c.wards(caller);
        // Call allowance on the share (which reverts on the underlying share call, but we just care about state change)
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.allowance.selector, caller, address(0x1)));
        // The call should revert because the underlying share contract doesn't exist
        assertTrue(!success);
        // After the call, wards mapping should be unchanged
        uint256 wardsAfter = c.wards(caller);
        assertTrue(wardsBefore == wardsAfter);
    }
}

