pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(0, bytes16(0), address(this), address(this), address(this));
    }

    function testFuzz_property(address caller, address spender) public {
        vm.assume(caller != address(0));
        vm.assume(spender != address(0));
        // ensure caller is not already authorized
        vm.assume(c.wards(caller) == 0);

        // drive through allowance
        vm.prank(caller);
        c.allowance(caller, spender);

        // general rule: after allowance, the caller's authorization remains unchanged (0)
        assertTrue(c.wards(caller) == 0);
    }
}

