pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(address owner, address spender) public {
        // The reference C's rely does nothing to allowance, so calling rely doesn't affect allowance.
        // For the mutant, rely is empty, so also doesn't affect allowance.
        // The property: allowance is unchanged after calling rely on any user.
        // We can call rely on any user (including owner or spender) and then allowance should match a fixed baseline.
        // Since we cannot rely on internal state, we directly compare allowance after rely with allowance after a second rely.
        // A simpler property: allowance is idempotent with respect to calling rely multiple times.
        // That is always true for reference (rely does nothing except auth check and event) and for mutant (rely does nothing).
        // But we need a difference: The reference's rely modifies wards[user] = 1 and emits event.
        // The mutant does nothing. So for reference, calling rely(user) sets wards[user]=1, but that does not affect allowance.
        // The property we can check: calling rely(owner) does NOT change allowance(owner, spender).
        // We read allowance before and after rely and assert they are equal.
        // For reference: wards[owner] becomes 1, but allowance is unchanged. For mutant: same result. So this still passes.
        // Wait - we need a general rule that reference satisfies and mutant breaks.
        // The difference: In reference, rely(user) is auth protected. In mutant, rely(user) is also auth protected but does nothing.
        // Both will revert if caller is not authorized. So the behavior is same for authorized callers.
        // Actually the mutant's rely does nothing, so no state change. Reference's rely sets wards[user]=1.
        // But that does not affect any public getter except wards(user) (which is public).
        // So we can read wards(user) after calling rely(user) as an authorized user.
        // In reference, wards(user) becomes 1. In mutant, it stays 0.
        // The getter wards is auto-generated because it's public.
        // So property: after calling rely(user) as an authorized user, wards(user) == 1.
        // But for the mutant, it's 0. That's a difference.
        // So we can test: call rely(authorizedUser) then check wards(authorizedUser).
        // We need to be authorized: the deployer (this contract) is authorized. So we can call rely on some user and then check wards.
        vm.assume(owner != address(0));
        // First, get initial wards for owner
        uint256 initialWards = c.wards(owner);
        c.rely(owner);
        uint256 afterRelyWards = c.wards(owner);
        // For reference: afterRelyWards == 1. For mutant: afterRelyWards == initialWards (==0 unless owner was already authorized).
        // But initialWards may be 1 if owner is msg.sender (the deployer). We need a general rule.
        // Let's use a parameter: a user that is not initially authorized.
        vm.assume(c.wards(owner) == 0);
        c.rely(owner);
        // For reference, now wards(owner) == 1. For mutant, still 0.
        assertTrue(c.wards(owner) == 1, "rely should set wards to 1");
    }
}

