pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(address owner, address spender, uint256 amount) public {
        // Ensure share.allowance is deterministic for the given inputs
        vm.assume(owner != address(0) && spender != address(0));
        // Call allowance through C
        (bool success, bytes memory data) = address(c).call(
            abi.encodeWithSignature("allowance(address,address)", owner, spender)
        );
        // The reference C always succeeds and returns the same value as the underlying share
        assertTrue(success);
        uint256 cAllowance = abi.decode(data, (uint256));
        // Directly call share.allowance (which is the same as c.share().allowance(owner, spender))
        // Since share is deployed at address(this) in setUp, we can call it directly
        (bool success2, bytes memory data2) = address(this).call(
            abi.encodeWithSignature("allowance(address,address)", owner, spender)
        );
        assertTrue(success2);
        uint256 shareAllowance = abi.decode(data2, (uint256));
        // The general rule: c.allowance always matches the underlying token's allowance
        assertTrue(cAllowance == shareAllowance);
    }
}

