import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(address user) public {
        // Precondition: Ensure user is not the contract itself to avoid auth issues
        vm.assume(user != address(this));

        // Record initial wards value for the user
        uint256 initialWards = c.wards(user);

        // Call allowance to trigger the bug (the mutant lacks the denial setting)
        // Note: We need to call with the auth modifier satisfied, so we set wards[msg.sender] first
        vm.startPrank(address(this));
        c.deny(user);
        vm.stopPrank();

        // Call allowance (any address, any address, any value)
        c.allowance(address(0), address(0));

        // Assert that the user's wards value is unchanged (0 bytes32)
        uint256 finalWards = c.wards(user);
        assertTrue(initialWards == finalWards, "wards(user) changed");
    }
}

