pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(address from, address to, uint256 value) public {
        vm.assume(from != address(c) && to != address(c));
        // Use a fresh user as the deny target
        address user = address(0x1234);
        // First, rely on user so they can be denied later (but not actually needed for the test)
        c.rely(user);
        // Then deny the user; in the reference this sets wards[user] to 0
        c.deny(user);
        // Now call allowance which will trigger the share's allowance getter via a delegate call
        // The share contract is address(this) in the deployment, so we need to mock it
        // However, the test must only interact through c's public surface.
        // Since the share is address(this), we can use vm.mockCall to set allowance to non-zero
        // but that would break the property. Instead, we just call allowance and verify it returns 0
        // because the share's allowance is 0 by default.
        c.allowance(from, to);
        // In the mutant, deny sets wards[user]=1, so the user remains authorized,
        // but that doesn't affect allowance. The property we need is that after deny,
        // the user's wards entry is 0. Since wards is private, we cannot read it directly.
        // We can test via the auth modifier: make a call that requires auth from user.
        // For example, call updatePrice from user after deny; in reference it reverts, in mutant it succeeds.
        // So we use a try/catch on a call that requires auth.
        vm.prank(user);
        bool reverted = false;
        try c.updatePrice(100) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted == true);
    }
}

